import os,re,json

session_dir = os.environ['RLM_SESSION_DIR']
content = open(session_dir+'/../../sessions/'+os.path.basename(session_dir)+'.jsonl').read()

# Split into JSON objects and find demo-related ones
objects = []
for line in content.split('\n'):
    if line.strip():
        try:
            obj = json.loads(line)
            full_text = obj.get('content', '')
            if isinstance(full_text, str):
                full_text = full_text.replace('\\n', '\n')
            objects.append((obj['id'], full_text))
        except:
            pass

# Find demo pair 1 in objects
for obj_id, full_text in objects:
    if 'Demo pair 1 input (18x17)' in full_text:
        print("Found demo pair 1!")
        # Find output
        output_match = re.search(r'Demo pair 1 output \(18x17\):\n', full_text)
        if output_match:
            print("\nFound output section!")
            # Extract the grids
            in_match = re.search(r'Demo pair 1 input \(18x17\):\n(\d+ \d+ .*)\nDemo pair 1 output', full_text, re.DOTALL)
            if in_match:
                input_lines = in_match.group(1).split('\n')
                print(f"Input rows: {len(input_lines)}")
                for i, row in enumerate(input_lines[:3]):
                    print(f"Row {i}: {row}")
                print(f"...")
                input_grid = [[int(x) for x in row.split()] for row in input_lines]
                print("Input grid shape:", len(input_grid), len(input_grid[0]))

                out_match = re.search(r'Demo pair 1 output \(18x17\):\n(\d+ \d+ .*)\n', full_text, re.DOTALL)
                if out_match:
                    output_lines = out_match.group(1).split('\n')
                    output_grid = [[int(x) for x in row.split()] for row in output_lines]
                    print("Output grid shape:", len(output_grid), len(output_grid[0]))

                    # Compare
                    diffs = []
                    for r in range(len(input_grid)):
                        for c in range(len(input_grid[0])):
                            if input_grid[r][c] != output_grid[r][c]:
                                diffs.append((r, c, input_grid[r][c], output_grid[r][c]))
                                print(f"Diff at ({r},{c}): {input_grid[r][c]} -> {output_grid[r][c]}")
                    print("Total differences:", len(diffs))

